require_once __DIR__.'/includes/learning-tools.php';$rows=[];$custom=[];$attempts=[];try{$rows=$lessonModel->getUserLessons($learnUserId);}catch(Throwable $e){}try{learn_ensure_tables();$q=learn_db()->prepare('SELECT cl.id,cl.title,cl.created_at,COUNT(cp.id) attempts,MAX(cp.score) best_score,MAX(cp.question_count) question_count FROM custom_lessons cl LEFT JOIN custom_lesson_progress cp ON cp.custom_lesson_id=cl.id AND cp.user_id=? WHERE cl.user_id=? GROUP BY cl.id ORDER BY cl.created_at DESC');$q->execute([$learnUserId,$learnUserId]);$custom=$q->fetchAll();}catch(Throwable $e){error_log('[path custom] '.$e->getMessage());}
learn_header('Mapa de progreso','Tu avance real en las lecciones de la base de datos y tus cuestionarios personalizados.');$done=0;foreach($rows as $r)if(!empty($r['completed']))$done++;echo '<section class="learn-panel"><div class="learn-grid"><article class="learn-card"><span class="learn-badge">LECCIONES</span><div class="learn-result-score">'.$done.'</div><p class="learn-muted">de '.count($rows).' lecciones registradas completadas</p></article><article class="learn-card"><span class="learn-badge">PERSONALIZADAS</span><div class="learn-result-score">'.count($custom).'</div><p class="learn-muted">cuestionarios creados por ti</p></article></div></section><section class="learn-panel"><h2>Progreso curricular</h2>';
if(!$rows)echo '<p class="learn-muted">No hay lecciones cargadas en la tabla lessons. La ruta visual del panel principal sigue disponible, pero para registrar progreso aquí deben existir lecciones y elementos en la base de datos.</p>';else{echo '<div class="learn-grid">';foreach($rows as $r){$complete=!empty($r['completed']);echo '<article class="learn-card"><span class="learn-badge">'.($complete?'✓ COMPLETADA':'EN PROGRESO').'</span><h3>'.learn_h($r['icon']??'✦').' '.learn_h($r['title']).'</h3><div class="learn-progress"><i style="width:'.($complete?100:0).'%"></i></div><p class="learn-muted">Mejor puntuación: '.(int)($r['user_score']??0).' · Precisión: '.(float)($r['user_accuracy']??0).'%</p><a class="learn-button secondary" href="lesson.php?id='.(int)$r['id'].'">'.($complete?'Repasar':'Continuar').'</a></article>'; }echo '</div>'; }echo '</section><section class="learn-panel"><h2>Cuestionarios personales</h2>';if(!$custom)echo '<p class="learn-muted">Aún no has creado lecciones personalizadas.</p>';else foreach($custom as $c)echo '<article class="learn-card"><h3>'.learn_h($c['title']).'</h3><p class="learn-muted">Intentos: '.(int)$c['attempts'].' · Mejor resultado: '.(int)($c['best_score']??0).'/'.(int)($c['question_count']??0).'</p><a class="learn-button" href="custom-lesson.php?id='.(int)$c['id'].'">Abrir</a></article>';echo '<p><a class="learn-button" href="lessons.php">Volver a lecciones</a></p></section>';learn_footer();
